import {icon,esc,btn,fmt,topologySVG} from './ui.js';
import {workspace,traceView,reportView,methodology,stats,settings,inspector,routeInspector,eventRows} from './views.js';
const $=(q,root=document)=>root.querySelector(q),main=$('#main');
const configDefaults={mode:'compare',protocol:'OSPF',source:'PC1',target:'PC2',duration:25,rate:20,size:512,trials:1,timer_profile:'lab',failure_link:'L3',failure_at:10};
const s={topology:{nodes:[],links:[]},config:{...configDefaults},snap:{busy:false,phase:'idle',message:'Ready',events:[],results:[],live:{},routes:{}},selected:null,tool:'select',connectSource:null,dirty:true,undo:[],zoom:1,offline:true,view:'workspace',cache:new Map(),activeRun:null,activeResult:null,selectedBatch:null,batchRuns:[],selectedPacket:1,packetFilter:'all',packetSearch:'',packetPage:0,logFilter:'all',drag:null,modalBusy:false};
let toastTimer, pollBusy=false,lastResultIDs='',lastLiveKey='',lastEvents='',lastRoutes='',currentProbe='ping';
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4500);}
async function api(path,data){const response=await fetch('/api'+path,{method:data===undefined?'GET':'POST',headers:data===undefined?{}:{'Content-Type':'application/json','X-CN-Sim':'1'},body:data===undefined?undefined:JSON.stringify(data)});const body=await response.json();if(!response.ok){let message=body.detail||'Request failed';if(Array.isArray(message))message=message.map(x=>x.msg).join('; ');throw Error(message);}return body;}
function save(){try{localStorage.setItem('cn-sim-workspace',JSON.stringify({topology:s.topology,config:s.config}));}catch{toast('Browser storage is full. Download your topology to save it.');}}
function remember(){s.undo.push(structuredClone(s.topology));if(s.undo.length>50)s.undo.shift();}
function changed(){s.dirty=true;save();}
function render(){const views={workspace,packets:traceView,report:reportView,methodology};main.innerHTML=views[s.view](s);$('#tabs').innerHTML=[['workspace','Workspace'],['packets','Packet inspector'],['report','Report'],['methodology','Methodology']].map(([v,t])=>`<a href="#${v}" class="${s.view===v?'active':''}">${t}</a>`).join('');$('#rail-nav').innerHTML=[['workspace','network','Workspace'],['packets','trace','Packet inspector'],['report','chart','Report'],['methodology','book','Methodology']].map(([v,i,t])=>`<a class="rail-link ${s.view===v?'active':''}" href="#${v}" title="${t}" aria-label="${t}">${icon(i)}</a>`).join('');renderLive();bindCanvas();}
function renderLive(){const el=$('#backend-state');el.innerHTML=`<span class="status-dot ${s.offline?'off':''}"></span><span class="state-copy">${s.offline?'Backend offline':s.snap.busy?'Experiment running':'FRRouting connected'}</span>`;const banner=$('#live-banner');if(banner){banner.hidden=!s.snap.busy&&!s.snap.error;banner.className='live-banner '+(s.snap.error?'error':'');banner.innerHTML=`<span>${s.snap.busy?'<span class="spinner" style="display:inline-block;margin-right:7px"></span>':''}${esc(s.snap.message)}${s.snap.busy?` <span class="mono" style="margin-left:10px">${fmt(s.snap.progress,0)}%</span>`:''}</span>${s.snap.busy?btn('Stop','stop','stop','small danger'):''}`;}if(s.view==='workspace'){$('#stats').outerHTML=stats(s);const badge=$('#canvas-badge-text');if(badge)badge.textContent=s.dirty?'UNAPPLIED CHANGES':s.snap.lab?'REAL NETWORK · '+s.snap.lab.protocol:'TOPOLOGY EDITOR';}}
function redrawTopology(){const svg=$('#topology');if(svg)svg.innerHTML=topologySVG(s.topology,{selected:s.selected,live:!s.dirty?s.snap.lab:null});}
function redrawInspector(){if($('#inspector'))$('#inspector').innerHTML=inspector(s);}
function redrawSettings(){if($('#settings'))$('#settings').innerHTML=settings(s);}
function route(){const hash=location.hash.slice(1);s.view=['workspace','packets','report','methodology'].includes(hash)?hash:'workspace';render();}
function assertEditable(){if(s.snap.busy)throw Error('Wait for the current operation to finish, or stop it first.');}
function validated(top){if(!top||!Array.isArray(top.nodes)||!Array.isArray(top.links))throw Error('A topology needs nodes and links arrays.');if(top.nodes.length>20||top.links.length>40)throw Error('Use at most 20 devices and 40 links.');const ids=new Set(),lids=new Set(),pairs=new Set();for(const n of top.nodes){if(!/^[A-Za-z][A-Za-z0-9_-]{0,15}$/.test(n.id)||ids.has(n.id)||!['router','host'].includes(n.type)||!Number.isFinite(n.x)||!Number.isFinite(n.y)||n.x<30||n.x>1170||n.y<30||n.y>670)throw Error('Invalid device or duplicate device ID.');ids.add(n.id);}for(const l of top.links){const pair=[l.a,l.b].sort().join('|');if(!/^[A-Za-z][A-Za-z0-9_-]{0,15}$/.test(l.id)||lids.has(l.id)||pairs.has(pair)||!ids.has(l.a)||!ids.has(l.b)||l.a===l.b||!Number.isFinite(l.bandwidth)||l.bandwidth<.1||l.bandwidth>1000||!Number.isFinite(l.delay)||l.delay<0||l.delay>100||typeof l.up!=='boolean'||(l.loss!==undefined&&(!Number.isFinite(l.loss)||l.loss<0||l.loss>20)))throw Error('Invalid connection, bandwidth, delay, loss, or link state.');lids.add(l.id);pairs.add(pair);l.loss??=0;}return structuredClone(top);}
function validateDeploy(){validated(s.topology);if(s.topology.nodes.length<2||!s.topology.links.length)throw Error('Connect at least two devices before deploying.');if(!s.topology.nodes.some(n=>n.type==='router'))throw Error('Add at least one router.');for(const n of s.topology.nodes.filter(n=>n.type==='host')){const links=s.topology.links.filter(l=>[l.a,l.b].includes(n.id));if(links.length!==1)throw Error(`${n.id} needs exactly one connection to a router.`);const l=links[0],peer=s.topology.nodes.find(x=>x.id===(l.a===n.id?l.b:l.a));if(peer.type!=='router')throw Error('Connect hosts to routers.');}}
function fixEndpoints(){const ids=s.topology.nodes.map(n=>n.id),hosts=s.topology.nodes.filter(n=>n.type==='host').map(n=>n.id);if(!ids.includes(s.config.source))s.config.source=hosts[0]||ids[0]||'';if(!ids.includes(s.config.target)||s.config.source===s.config.target)s.config.target=hosts.find(n=>n!==s.config.source)||ids.find(n=>n!==s.config.source)||'';if(s.config.failure_link&&!s.topology.links.some(l=>l.id===s.config.failure_link&&l.up))s.config.failure_link='';}
async function loadRun(id){if(!s.cache.has(id))s.cache.set(id,await api('/results/'+id));return s.cache.get(id);}
async function selectRun(id){s.activeRun=id;s.activeResult=await loadRun(id);s.selectedPacket=s.activeResult.packets[0]?.id||1;s.packetPage=0;}
async function selectBatch(batch){s.selectedBatch=batch;const ids=s.snap.results.filter(r=>r.batch===batch).map(r=>r.id);s.batchRuns=await Promise.all(ids.map(loadRun));}
async function poll(){if(pollBusy)return;pollBusy=true;try{const previousBusy=s.snap.busy;const snap=await api('/state');const wasOffline=s.offline;s.offline=false;s.snap=snap;const ids=snap.results.map(r=>r.id).join(',');let resultsChanged=ids!==lastResultIDs;if(resultsChanged){lastResultIDs=ids;const latest=snap.results.at(-1);if(latest){await selectRun(latest.id);await selectBatch(latest.batch);}}
const liveKey=JSON.stringify([snap.busy,snap.lab?.protocol,snap.lab?.links,s.dirty,s.offline]);if((liveKey!==lastLiveKey||wasOffline)&&!s.drag){lastLiveKey=liveKey;if(s.view==='workspace')render();}
if(s.view==='workspace'){const events=JSON.stringify(snap.events);if(events!==lastEvents){lastEvents=events;$('#event-rows').innerHTML=eventRows(s);}const routes=JSON.stringify(snap.routes);if(routes!==lastRoutes){lastRoutes=routes;if(s.selected?.kind==='node'&&$('#inspector-routes'))$('#inspector-routes').innerHTML=routeInspector(s,s.selected.id);}}
if(resultsChanged&&['packets','report'].includes(s.view))render();else renderLive();if(previousBusy&&!snap.busy&&snap.error)toast(snap.error);
}catch(e){if(!s.offline){s.offline=true;renderLive();redrawSettings();toast('Backend connection lost. Start Docker and run docker compose up -d.');}}finally{pollBusy=false;}}
function download(name,data,type='application/json'){const blob=new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function modal(title,body){$('#modal-content').innerHTML=`<div class="modal-header"><h2>${esc(title)}</h2>${btn('Close','modal-close','close','small ghost')}</div><div class="modal-body">${body}</div>`;if(!$('#modal').open)$('#modal').showModal();}
function probeModal(kind){if(s.dirty)throw Error('Deploy the edited topology before probing.');currentProbe=kind;const choices=s.topology.nodes.map(n=>[n.id,n.id]);modal(kind==='ping'?'Send a real ping':'Run a real traceroute',`<p>Select the endpoints in your deployed ${s.snap.lab?.protocol} network.</p><div class="field-row" style="margin-top:18px"><div class="field"><label for="probe-source">Source</label><select id="probe-source">${choices.map(([v])=>`<option ${s.config.source===v?'selected':''}>${esc(v)}</option>`).join('')}</select></div><div class="field"><label for="probe-target">Destination</label><select id="probe-target">${choices.map(([v])=>`<option ${s.config.target===v?'selected':''}>${esc(v)}</option>`).join('')}</select></div></div>${btn(kind==='ping'?'Send ping':'Trace route','probe-run','play','primary')}<pre id="probe-output">Ready.</pre>`);}
async function action(name,el){
if(name.startsWith('tool-')){assertEditable();s.tool=name.slice(5);s.connectSource=null;render();return;}
if(name.startsWith('mode-')){assertEditable();s.config.mode=name.slice(5);save();redrawSettings();return;}
if(name==='modal-close'){$('#modal').close();return;}
if(name==='save'){download('CN-Sim-topology.json',s.topology);toast('Topology downloaded.');return;}
if(name==='import'){$('#import-file').click();return;}
if(name==='example'){assertEditable();remember();s.topology=validated(await fetch('/examples/redundant.json').then(r=>r.json()));s.selected=null;s.config={...s.config,source:'PC1',target:'PC2',failure_link:'L3'};changed();render();toast('Redundant example topology loaded.');return;}
if(name==='clear'){assertEditable();remember();s.topology={nodes:[],links:[]};s.selected=null;s.config.failure_link='';changed();render();return;}
if(name==='undo'){assertEditable();if(s.undo.length){s.topology=s.undo.pop();s.selected=null;fixEndpoints();changed();render();}return;}
if(name==='add-router'||name==='add-host'){assertEditable();if(s.topology.nodes.length>=20)throw Error('The lab supports up to 20 devices.');remember();const type=name==='add-router'?'router':'host',prefix=type==='router'?'R':'PC';let i=1;while(s.topology.nodes.some(n=>n.id===prefix+i))i++;const n={id:prefix+i,type,x:190+(s.topology.nodes.length%5)*165,y:125+Math.floor(s.topology.nodes.length/5)*125};s.topology.nodes.push(n);s.selected={kind:'node',id:n.id};fixEndpoints();changed();render();return;}
if(name==='delete'){assertEditable();if(!s.selected)return;remember();const {kind,id}=s.selected;if(kind==='node'){s.topology.nodes=s.topology.nodes.filter(n=>n.id!==id);s.topology.links=s.topology.links.filter(l=>![l.a,l.b].includes(id));}else s.topology.links=s.topology.links.filter(l=>l.id!==id);s.selected=null;fixEndpoints();changed();render();return;}
if(name.startsWith('zoom-')){s.zoom=name==='zoom-fit'?1:Math.max(.65,Math.min(2,s.zoom+(name==='zoom-in'?.15:-.15)));render();return;}
if(name==='deploy'){validateDeploy();await api('/lab/deploy',{topology:s.topology,protocol:s.config.protocol,timer_profile:s.config.timer_profile});s.dirty=false;s.snap.busy=true;s.snap.message='Deploying virtual network…';s.snap.error=null;render();await poll();return;}
if(name==='run'){validateDeploy();const c=s.config;if(c.source===c.target)throw Error('Choose different traffic endpoints.');await api('/experiments',{...c,protocols:c.mode==='compare'?['RIP','OSPF','EIGRP']:[c.protocol],topology:s.topology,failure_link:c.failure_link||null});s.dirty=false;s.snap.busy=true;s.snap.message='Starting experiment…';s.snap.error=null;render();await poll();return;}
if(name==='stop'){await api('/lab/stop',{});toast(s.snap.busy?'Stopping the current operation…':'Removing virtual network…');await poll();return;}
if(name==='toggle-link'){assertEditable();const l=s.topology.links.find(l=>l.id===s.selected?.id);if(!l)return;const live=!s.dirty?s.snap.lab?.links?.[l.id]:null,up=!(live?live.up:l.up);if(live){await api('/lab/link/'+l.id,{up});l.up=up;save();await poll();}else{remember();l.up=up;changed();}fixEndpoints();render();return;}
if(name==='inspect'){const id=s.selected?.id;if(!id)return;modal(id+' · routing inspection','<p>Reading real daemon state…</p>');const r=await api('/lab/node/'+encodeURIComponent(id));modal(id+' · routing inspection',`<h3>Routing table</h3><pre>${esc(r.routes_text||JSON.stringify(r.routes,null,2))}</pre><h3>Protocol / interfaces</h3><pre>${esc(r.details)}</pre><h3>Generated configuration</h3><pre>${esc(r.config)}</pre>`);return;}
if(name==='ping'||name==='trace'){probeModal(name);return;}
if(name==='probe-run'){if(s.modalBusy)return;s.modalBusy=true;el.disabled=true;$('#probe-output').textContent='Running real network probes…';try{const r=await api('/probe',{kind:currentProbe,source:$('#probe-source').value,target:$('#probe-target').value});$('#probe-output').textContent=r.output;}finally{s.modalBusy=false;if(document.contains(el))el.disabled=false;}return;}
if(name==='log-filter'){s.logFilter=el.dataset.filter;render();return;}
if(name==='select-packet'){s.selectedPacket=Number(el.dataset.packet);render();return;}
if(name==='packet-next'||name==='packet-prev'){s.packetPage=Math.max(0,s.packetPage+(name==='packet-next'?1:-1));render();return;}
if(name==='result-trace'){modal('Real traceroute snapshot',`<p>Independent ICMP diagnostic probes recorded after this run. This may differ from an individual UDP packet's path.</p><pre>${esc(s.activeResult?.traceroute)}</pre>`);return;}
if(name==='open-run'){await selectRun(el.dataset.run);location.hash='packets';if(s.view==='packets')render();return;}
if(name==='export-csv'){if(s.activeRun)location.href='/api/export/'+s.activeRun+'/csv';return;}
if(name==='export-report'){download('CN-Sim-comparison-'+s.selectedBatch+'.json',{title:'CN-Sim routing comparison',batch:s.selectedBatch,exported:new Date().toISOString(),scoring:'0.4 delivery + 0.2 latency + 0.25 convergence + 0.15 control efficiency. See methodology in README.',runs:s.batchRuns});return;}
if(name==='print'){window.print();return;}
}
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el||el.disabled)return;event.preventDefault();action(el.dataset.action,el).catch(e=>toast(e.message));});
document.addEventListener('change',async event=>{const el=event.target;try{if(el.matches('[data-config]')){const name=el.dataset.config;const v=el.type==='number'||['duration','rate','size','trials','failure_at'].includes(name)?Number(el.value):el.value;s.config[name]=v;if(name==='failure_link')redrawSettings();save();}if(el.matches('[data-link-field]')){assertEditable();const l=s.topology.links.find(l=>l.id===s.selected?.id);const prop=el.dataset.linkField,value=Number(el.value),limits={bandwidth:[.1,1000],delay:[0,100],loss:[0,20]};if(!Number.isFinite(value)||value<limits[prop][0]||value>limits[prop][1])throw Error('Value is outside the supported range.');remember();l[prop]=value;changed();redrawTopology();renderLive();}if(el.id==='run-select'){await selectRun(el.value);render();}if(el.id==='batch-select'){await selectBatch(el.value);render();}if(el.id==='packet-filter'){s.packetFilter=el.value;s.packetPage=0;render();}if(el.id==='import-file'){assertEditable();const file=el.files[0];if(!file)return;if(file.size>1000000)throw Error('Topology files must be smaller than 1 MB.');const top=validated(JSON.parse(await file.text()));remember();s.topology=top;s.selected=null;fixEndpoints();changed();render();el.value='';toast('Topology imported.');}}catch(e){toast(e.message);if(el.matches('[data-link-field]'))redrawInspector();}});
let searchTimer;document.addEventListener('input',e=>{if(e.target.id==='packet-search'){s.packetSearch=e.target.value;s.packetPage=0;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{const pos=e.target.selectionStart;render();$('#packet-search')?.focus();$('#packet-search')?.setSelectionRange(pos,pos);},350);}});
document.addEventListener('keydown',e=>{if(e.target.matches('input,select,textarea')||$('#modal').open)return;const key=e.key.toLowerCase();if((e.ctrlKey||e.metaKey)&&key==='z'){e.preventDefault();action('undo',{}).catch(x=>toast(x.message));}else if(key==='delete'||key==='backspace'){e.preventDefault();action('delete',{}).catch(x=>toast(x.message));}else if(key==='c')action('tool-connect',{}).catch(x=>toast(x.message));else if(key==='v'||key==='escape')action('tool-select',{}).catch(x=>toast(x.message));});
function bindCanvas(){const svg=$('#topology');if(!svg)return;const point=e=>{const pt=svg.createSVGPoint();pt.x=e.clientX;pt.y=e.clientY;return pt.matrixTransform(svg.getScreenCTM().inverse());};svg.addEventListener('pointerdown',e=>{if(s.snap.busy)return;const nodeEl=e.target.closest('[data-node]'),linkEl=e.target.closest('[data-link]');if(nodeEl){const id=nodeEl.dataset.node;if(s.tool==='connect'){connect(id);return;}s.selected={kind:'node',id};const n=s.topology.nodes.find(n=>n.id===id),p=point(e);s.drag={id,dx:p.x-n.x,dy:p.y-n.y,original:structuredClone(s.topology),moved:false};svg.setPointerCapture(e.pointerId);redrawTopology();redrawInspector();}else if(linkEl){s.selected={kind:'link',id:linkEl.dataset.link};redrawTopology();redrawInspector();}else{s.selected=null;redrawTopology();redrawInspector();}});svg.addEventListener('pointermove',e=>{if(!s.drag)return;const n=s.topology.nodes.find(n=>n.id===s.drag.id),p=point(e);n.x=Math.round(Math.max(42,Math.min(1058,p.x-s.drag.dx)));n.y=Math.round(Math.max(60,Math.min(545,p.y-s.drag.dy)));s.drag.moved=true;redrawTopology();});const end=()=>{if(s.drag?.moved){s.undo.push(s.drag.original);save();}s.drag=null;};svg.addEventListener('pointerup',end);svg.addEventListener('pointercancel',end);svg.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){const node=e.target.closest('[data-node]');if(!node)return;e.preventDefault();if(s.tool==='connect')connect(node.dataset.node);else{s.selected={kind:'node',id:node.dataset.node};redrawInspector();redrawTopology();}}});}
function connect(id){try{assertEditable();if(!s.connectSource){s.connectSource=id;s.selected={kind:'node',id};render();return;}const from=s.connectSource;s.connectSource=null;if(from===id){render();return;}if(s.topology.links.some(l=>[l.a,l.b].includes(from)&&[l.a,l.b].includes(id)))throw Error('These devices are already connected.');if(s.topology.links.length>=40)throw Error('The lab supports 40 links.');for(const n of [from,id].map(id=>s.topology.nodes.find(n=>n.id===id))){if(n.type==='host'&&s.topology.links.some(l=>[l.a,l.b].includes(n.id)))throw Error('Each end host supports one router connection.');}if([from,id].every(id=>s.topology.nodes.find(n=>n.id===id).type==='host'))throw Error('Connect hosts to routers.');remember();let i=1;while(s.topology.links.some(l=>l.id==='L'+i))i++;const l={id:'L'+i,a:from,b:id,bandwidth:100,delay:2,loss:0,up:true};s.topology.links.push(l);s.selected={kind:'link',id:l.id};changed();render();}catch(e){toast(e.message);render();}}
window.addEventListener('hashchange',route);
async function boot(){try{const saved=JSON.parse(localStorage.getItem('cn-sim-workspace'));if(saved){s.topology=validated(saved.topology);s.config={...configDefaults,...saved.config};}else s.topology=await fetch('/examples/redundant.json').then(r=>r.json());}catch{s.topology=await fetch('/examples/redundant.json').then(r=>r.json());}fixEndpoints();route();await poll();setInterval(poll,1200);}
boot().catch(e=>{main.innerHTML=`<section class="panel empty-state"><h1>Could not load CN-Sim</h1><p>${esc(e.message)}</p><button class="btn" onclick="location.reload()">Reload</button></section>`;});
